waitingNodeTooltip:
={{ ((parameters, resumeUrl, formResumeUrl) => {
    const resume = parameters.resume;
    if (['webhook', 'form'].includes(resume)) {
        const { webhookSuffix } = (parameters.options ?? {});
        const suffix = webhookSuffix && typeof webhookSuffix !== 'object' ? `/${webhookSuffix}` : '';
        let message = '';
        const url = `${resume === 'form' ? formResumeUrl : resumeUrl}${suffix}`;
        if (resume === 'form') {
            message = 'Execution will continue when form is submitted on ';
        }
        if (resume === 'webhook') {
            message = 'Execution will continue when webhook is received on ';
        }
        return `${message}<a href="${url}" target="_blank">${url}</a>`;
    }
    return 'Execution will continue when wait time is over';
})($parameter, $execution.resumeUrl, $execution.resumeFormUrl) }}

webhooks.responseCode:
={{((parameters) => {
    if (parameters.responseCode) {
        return parameters.responseCode;
    }
    const responseCodeOptions = parameters.options;
    if (responseCodeOptions?.responseCode?.values) {
        const { responseCode, customCode } = responseCodeOptions.responseCode.values;
        if (customCode) {
            return customCode;
        }
        return responseCode;
    }
    return 200;
})($parameter)}}

outputs:
={{((parameters) => {
    const httpMethod = parameters.httpMethod;
    if (!Array.isArray(httpMethod))
        return [
            {
                type: 'main',
                displayName: httpMethod,
            },
        ];
    const outputs = httpMethod.map((method) => {
        return {
            type: 'main',
            displayName: method,
        };
    });
    return outputs;
})($parameter)}}

