webhooks.responseData:
={{((parameters) => {
    const { responseData, responseMode, options } = parameters;
    if (responseData)
        return responseData;
    if (responseMode === 'onReceived') {
        const data = options?.responseData;
        if (data)
            return data;
    }
    if (options?.noResponseBody)
        return 'noData';
    return undefined;
})($parameter)}}

